using PlayerOne.Windows.Services;namespace PlayerOne.Windows;public partial class SettingsWindow:System.Windows.Window{public SettingsWindow(){InitializeComponent();var x=PlayerSettings.Load();Reconnect.IsChecked=x.AutoReconnect;Background.IsChecked=x.BackgroundPlayback;Subs.IsChecked=x.SubtitlesEnabled;Remember.IsChecked=x.RememberLastSection;Select(Aspect,x.DefaultAspect);Select(Language,x.AppLanguage);Select(Audio,x.PreferredAudioLanguage);Select(Subtitle,x.PreferredSubtitleLanguage);}static void Select(System.Windows.Controls.ComboBox b,string v){foreach(System.Windows.Controls.ComboBoxItem i in b.Items)if(i.Content?.ToString()==v){b.SelectedItem=i;break;}}static string Val(System.Windows.Controls.ComboBox b,string d)=>(b.SelectedItem as System.Windows.Controls.ComboBoxItem)?.Content?.ToString()??d;void Save_Click(object s,System.Windows.RoutedEventArgs e){var o=PlayerSettings.Load();PlayerSettings.Save(o with{AutoReconnect=Reconnect.IsChecked==true,BackgroundPlayback=Background.IsChecked==true,SubtitlesEnabled=Subs.IsChecked==true,RememberLastSection=Remember.IsChecked==true,DefaultAspect=Val(Aspect,"fill"),AppLanguage=Val(Language,"ar"),PreferredAudioLanguage=Val(Audio,"auto"),PreferredSubtitleLanguage=Val(Subtitle,"auto")});Close();}}